-- Verificação rápida
DO $$
DECLARE
  total_e1 numeric; total_e2 numeric; cnt_e1 int; cnt_e2 int;
BEGIN
  SELECT COALESCE(SUM(valor_venda),0), COUNT(*) INTO total_e1, cnt_e1
    FROM core.obras WHERE empresa_id='11111111-1111-1111-1111-111111111111';
  SELECT COALESCE(SUM(valor_venda),0), COUNT(*) INTO total_e2, cnt_e2
    FROM core.obras WHERE empresa_id='22222222-2222-2222-2222-222222222222';
  RAISE NOTICE 'Empresa 1 (Pisos): % obras totalizando R$ %', cnt_e1, total_e1;
  RAISE NOTICE 'Empresa 2 (Marc.): % obras totalizando R$ %', cnt_e2, total_e2;
  RAISE NOTICE 'TOTAL GERAL: R$ %', total_e1 + total_e2;
END $$;
